function Branches() {
  const [query, setQuery] = useState('');
  const [searched, setSearched] = useState(false);
  const branches = [
    'Quận 7 - Sunrise',
    'Tân Bình - Cộng Hòa',
    'Bình Thạnh - Pearl',
    'Gò Vấp - Nguyễn Oanh',
  ];
  const filtered = branches.filter((item) =>
    item.toLowerCase().includes(query.toLowerCase()),
  );
  return (
    <section className="branches-section" id="branches">
      <div className="container branch-layout">
        <div>
          <SectionHeading
            kicker="ALWAYS CLOSE TO YOU"
            title="Find your nearest gym"
            description="Choose a location that fits your routine."
          />
          <div className="search-box">
            <Search size={18} />
            <input
              aria-label="Search gyms by location"
              value={query}
              onChange={(e) => {
                setQuery(e.target.value);
                setSearched(false);
              }}
              onKeyDown={(e) => e.key === 'Enter' && setSearched(true)}
              placeholder="Enter a district, city or postcode"
            />
            <button onClick={() => setSearched(true)} aria-label="Search">
              <ArrowRight size={18} />
            </button>
          </div>
          {searched && (
            <p className="search-result">
              Found {filtered.length} matching gyms.
            </p>
          )}
        </div>
        <div className="branch-list">
          {filtered.slice(0, 3).map((branch, i) => (
            <div className="branch-item" key={branch}>
              <span className="branch-map">
                <MapPin size={18} />
              </span>
              <div>
                <b>{branch}</b>
                <small>
                  {i === 0
                    ? 'Open 24/7 · 1.2 km away'
                    : 'Open 24/7 · 3.5 km away'}
                </small>
              </div>
              <ArrowRight size={17} />
            </div>
          ))}
        </div>
      </div>
    </section>
  );
}

